import type { IncomingMessage } from "node:http";

// A declarations-only package typing a value the program builds itself, the
// way @types/express-serve-static-core types a request: a generic interface
// extending a stdlib type, parameterized over a record the caller picks.
export interface TypedBag<P = { [key: string]: string }> extends IncomingMessage {
  params: P;
}
